async function processRequest() {
  const body = document.querySelector('.ms-apiresults-body');
  if (!body) {
    console.log("no_container");
    return { error: 'no_container' };  
  }

  const buttonId = 'continue-btn-1';

  // 新增檢查：如果按鈕已存在，就不重複新增
  if (document.getElementById(buttonId)) {
    console.log('Button already exists, skipping creation');
    return { status: 'waiting_user_input', nodeId: ctx.node?.id || null, buttonId };
  }

  const btn = document.createElement('button');
  btn.id = buttonId;
  btn.innerText = 'Continue workflow';
  btn.className = 'ms-continue-btn';
  btn.onclick = () => {
    ctx.setVar('waiting_wait', false);
    document.dispatchEvent(new CustomEvent('workflowResume', { detail: { nodeId: ctx.node?.id } }));
    console.log('button click');
  };

  body.appendChild(btn);

  // set waiting flag to pause workflow
  ctx.setVar('waiting_wait', true);
  console.log("set waiting wait", true);
  return { status: 'waiting_user_input', nodeId: ctx.node?.id || null, buttonId };
}

