async function processRequest(ctx) {
  console.log("show Image Function", ctx.node?.id);

  const body = document.querySelector('.ms-apiresults-body');
  if (!body) {
    console.warn('ms-apiresults-body not found');
    return { error: 'no_container' };
  }

  const componentID = 'img-' + Date.now();
  const x = 0;
  const y = 0;
  const width = '50px';
  const height = '50px';
  const imageURL = "https://maxsolo.co.uk/images/uploads/img_69970ede6e00a3.96022462.jpg";

  try {
    const wrapper = document.createElement('div');
    wrapper.className = 'ms-apiresults-item';
    wrapper.id = componentID;
    wrapper.style.position = 'absolute';
    wrapper.style.left = x + 'px';
    wrapper.style.top = y + 'px';
    wrapper.style.width = width;
    wrapper.style.height = height;

    const img = document.createElement('img');
    img.src = imageURL;
    img.style.width = '100%';
    img.style.height = '100%';
    img.style.objectFit = 'contain';

    wrapper.appendChild(img);
    body.appendChild(wrapper);

    // Save a reference in storeVars for UI or later inspection
    if (typeof ctx.setVar === 'function') {
      ctx.setVar('last_api_component', { id: componentID, imageURL, nodeId: ctx.node?.id || null });
    }

    // Optionally pause the workflow (global flag used by runner)
    // ctx.setVar('waiting_wait', true);

    return { componentID, x, y, width, height, imageURL };
  } catch (err) {
    console.error('processRequest failed', err);
    return { error: String(err) };
  }
}

